      filename: "SharedStores.svelte",
      source: "<script lang=\"ts\">\n  import { writable } from 'svelte/store';\n  import type { Vector3Tuple } from 'svelte-typegpu';\n  import StoreViewport from './StoreViewport.typegpu.svelte';\n\n  let { frameloop = 'demand', maxDevicePixelRatio = 1.5, onready, onfps, onrenderererror } = $props();\n  const position = writable<Vector3Tuple>([0, 1, 0]);\n  const rotation = writable(0);\n  const selected = writable(false);\n\n  function reset() {\n    $position = [0, 1, 0];\n    $rotation = 0;\n    $selected = false;\n  }\n</script>\n\n<div class=\"store-workbench\">\n  <div class=\"store-scene\">\n    <StoreViewport {position} {rotation} {selected}\n      {frameloop} {maxDevicePixelRatio} {onready} {onfps} {onrenderererror} />\n  </div>\n  <div class=\"store-controls\" role=\"group\" aria-label=\"Shared scene state\">\n    <label>\n      <span>Position X</span>\n      <input type=\"range\" min=\"-3\" max=\"3\" step=\"0.1\" bind:value={$position[0]} />\n      <output>{$position[0].toFixed(1)}</output>\n    </label>\n    <label>\n      <span>Position Z</span>\n      <input type=\"range\" min=\"-2\" max=\"2\" step=\"0.1\" bind:value={$position[2]} />\n      <output>{$position[2].toFixed(1)}</output>\n    </label>\n    <label>\n      <span>Rotation</span>\n      <input type=\"range\" min=\"0\" max={Math.PI * 2} step=\"0.01\" bind:value={$rotation} />\n      <output>{Math.round($rotation * 180 / Math.PI)} deg</output>\n    </label>\n    <div class=\"store-actions\">\n      <label><input type=\"checkbox\" bind:checked={$selected} /> Selected</label>\n      <button type=\"button\" onclick={reset}>Reset</button>\n    </div>\n  </div>\n</div>\n\n<style>\n  .store-workbench { display: grid; grid-template-rows: minmax(0, 1fr) auto; height: 100%; min-width: 0; }\n  .store-scene { min-height: 0; }\n  .store-controls { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px 20px; padding: 16px 20px; background: #151919; border-top: 1px solid #394141; }\n  .store-controls > label { display: grid; grid-template-columns: minmax(0, 1fr) 7ch; align-items: center; gap: 8px; font-size: 12px; }\n  .store-controls > label > span { grid-column: 1 / -1; color: #d7dddd; }\n  input[type=\"range\"] { min-width: 0; width: 100%; accent-color: #65cda2; }\n  output { text-align: right; font-variant-numeric: tabular-nums; color: #d7dddd; }\n  .store-actions { grid-column: 1 / -1; display: flex; align-items: center; justify-content: space-between; gap: 16px; }\n  .store-actions label { display: flex; align-items: center; gap: 8px; font-size: 13px; }\n  input[type=\"checkbox\"] { accent-color: #e8c84b; }\n  button { padding: 6px 14px; border: 1px solid #525d5d; border-radius: 4px; background: #252d2d; color: #f0f3f3; font: inherit; font-size: 13px; cursor: pointer; }\n  button:hover { background: #354040; }\n  :focus-visible { outline: 2px solid #e8c84b; outline-offset: 3px; }\n  @media (max-width: 600px) {\n    .store-controls { grid-template-columns: 1fr; gap: 10px; padding: 12px; }\n    .store-controls > label { grid-template-columns: 76px minmax(0, 1fr) 7ch; }\n    .store-controls > label > span { grid-column: auto; }\n  }\n</style>\n",
